// Self-contained attack lifecycle. invoke() registers; the game loop drives.
export const AttackLifecycle = {
  _live: new Set(),
  // Register a handle if it needs per-frame driving (has .step or a .zone).
  register(h) { /* skip if h._completed || !needsDriving(h) */ },
  // Step every live handle once; prune completed/cancelled.
  stepAll(dt, targets) { /* for h of _live: h.step?.(dt, targets); prune */ },
  // Draw every live handle's zones (recursive over h.handles + h.zone).
  drawAll(ctx) { /* visit(h): h.zone?.draw(ctx); recurse h.handles */ },
  // Tear down all (level transition / teardown).
  clear() { /* cancel each; _live.clear() */ },
};
function needsDriving(h) { return typeof h?.step === 'function' || !!h?.zone; }

// A handle is driven by EXACTLY ONE owner: the registry OR a host.
// register(h, { owned }) - owned=true means a host already steps it;
//   the registry still DRAWS its zones but never calls h.step().
register(h, opts = {}) {
  if (!needsDriving(h)) return;
  this._live.add(h);
  h._registryStepped = !opts.owned; // false => host owns stepping
}
stepAll(dt, targets) {
  for (const h of [...this._live]) {
    if (h._completed || h._cancelled) { this._live.delete(h); continue; }
    if (h._registryStepped) h.step?.(dt, targets); // hosts step their own
  }
}

