// bombAttackHost.js spawn(): host owns stepping, registry only draws.
spawn(id, params, attacker) {
  const h = invoke(id, params, this.makeCtx(attacker));
  if (h and not completed) h._registryStepped = false; // host steps it
  return h;
}

